<?php defined( 'ABSPATH' ) || exit; $jsc_photos = jsc_gallery_photos( get_the_ID() ); $gallery_id = $args['_uid'] ?? wp_unique_id( 'jsc-gallery-' ); ?>
<aside class="jsc-job-sidebar" aria-label="Company information">
<?php $rating = get_post_meta( get_the_ID(), 'jsc_rating', true ); if ( is_numeric( $rating ) ) : ?><section class="jsc-sidebar-box"><h2><?php echo esc_html( $args['title'] ?? '' ); ?></h2><div class="jsc-rating" aria-label="<?php echo esc_attr( 'Design reference staff rating: ' . $rating . ' out of 5' ); ?>"><span aria-hidden="true"><?php for ( $star = 1; $star <= 5; $star++ ) : ?><span class="<?php echo $star > max( 0, min( 5, (float) $rating ) ) ? 'jsc-empty-star' : ''; ?>"><?php echo $star <= (float) $rating ? '★' : '☆'; ?></span> <?php endfor; ?></span> <b><?php echo esc_html( number_format_i18n( (float) $rating, 1 ) ); ?></b></div></section><?php endif; ?>
<?php if ( $jsc_photos ) : ?><section class="jsc-sidebar-box"><h2><?php echo esc_html( $args['photos_title'] ?? '' ); ?></h2><button type="button" class="jsc-gallery-open" aria-controls="<?php echo esc_attr( $gallery_id ); ?>" aria-label="<?php echo esc_attr( 'View ' . count( $jsc_photos ) . ' company photos' ); ?>"><img src="<?php echo esc_url( $jsc_photos[0]['url'] ); ?>" width="260" height="260" alt="<?php echo esc_attr( $jsc_photos[0]['alt'] ); ?>"><?php if ( count( $jsc_photos ) > 1 ) : ?><span aria-hidden="true">+<?php echo esc_html( count( $jsc_photos ) - 1 ); ?></span><?php endif; ?></button></section>
<?php endif; ?></aside>
<?php if ( $jsc_photos ) : ?><dialog class="jsc-gallery-dialog" id="<?php echo esc_attr( $gallery_id ); ?>" aria-labelledby="<?php echo esc_attr( $gallery_id ); ?>-title"><div class="jsc-gallery-toolbar"><h2 id="<?php echo esc_attr( $gallery_id ); ?>-title"><?php echo esc_html( $args['photos_title'] ?? '' ); ?></h2><button class="jsc-gallery-close" type="button" aria-label="Close photos">×</button></div><img class="jsc-gallery-large" src="<?php echo esc_url( $jsc_photos[0]['url'] ); ?>" alt="<?php echo esc_attr( $jsc_photos[0]['alt'] ); ?>"><div class="jsc-gallery-thumbnails"><?php foreach ( $jsc_photos as $photo ) : ?><button type="button" data-photo="<?php echo esc_url( $photo['url'] ); ?>" data-alt="<?php echo esc_attr( $photo['alt'] ); ?>"><img src="<?php echo esc_url( $photo['url'] ); ?>" alt="<?php echo esc_attr( $photo['alt'] ); ?>" width="90" height="70" loading="lazy"></button><?php endforeach; ?></div></dialog><?php endif; ?>
